import {dimensions,cycles,states,rowsFor,band,bandClass,auditsFor,plansFor,needsPlan,planSignals,fiscalProposal,adoptionBonus,methodologyVersion} from './data.js';
import {checklistContent} from './checklist-data.js';
import {createAnalyticsController} from './analytics.js';

const $=s=>document.querySelector(s);
const fmt=(n,d=1)=>Number(n).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const integer=n=>fmt(n,0);
const avg=(a,k)=>a.length?a.reduce((v,r)=>v+r[k],0)/a.length:0;
const sum=(a,k)=>a.reduce((v,r)=>v+r[k],0);
const percent=(n,d)=>d?n/d*100:0;
const latency=h=>h<24?`${fmt(h)} h`:`${fmt(h/24)} dias`;
const iconPaths={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0V3Z"/><path d="M8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v6m-4 2h8m-6-2h4"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v3"/>',
 book:'<path d="M12 5c-3-3-7-2-10-1v15c3-1 7-2 10 1 3-3 7-2 10-1V4c-3-1-7-2-10 1Zm0 0v15"/>',
 download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 trend:'<path d="m3 17 6-6 4 4 8-10m-6 0h6v6"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-6 7-6 11 0 18 6-7 6-11 0-18Z"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',
 contrast:'<circle cx="12" cy="12" r="9"/><path d="M12 3v18a9 9 0 0 0 0-18Z" fill="currentColor"/>',
 layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',
 flag:'<path d="M5 22V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0"/>',
 file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h8"/>',
 link:'<path d="m10 14 4-4m-6 1-2 2a4 4 0 0 0 6 6l3-3m-6-8 3-3a4 4 0 0 1 6 6l-2 2"/>'
};
const ico=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.grid}</svg>`;
const navs=[['geral','Visão geral','grid'],['ranking','Ranking das UFs','trophy'],['analitico','Analítico detalhado','layers'],['auditorias','Auditorias e planos','shield'],['participacao','Participação e evolução','people'],['checklist','Checklist do auditor','check'],['metodologia','Metodologia','book']];
const headings={
 geral:['PAINEL FEDERATIVO','Qualidade dos dados de segurança pública','Acompanhe o desempenho dos entes, reconheça avanços e direcione o apoio técnico.'],
 ranking:['DESEMPENHO E RECONHECIMENTO','Ranking das Unidades da Federação','Compare os componentes da qualidade dos dados e a evolução de cada ente.'],
 analitico:['DIAGNÓSTICO TERRITORIAL E INSTITUCIONAL','Análise detalhada da qualidade dos dados','Explore municípios, instituições e unidades para localizar gargalos e orientar a verificação.'],
 auditorias:['VERIFICAÇÃO E MELHORIA CONTÍNUA','Auditorias e planos de aprimoramento','Acompanhe verificações técnicas, responsáveis e planos de ação para integração.'],
 participacao:['COOPERAÇÃO FEDERATIVA','Participação e evolução dos entes','Reconheça a evolução, acompanhe compromissos e dê visibilidade à participação.'],
 checklist:['MANUAL E AUDITABILIDADE','Checklist operacional do auditor','Consulte os 21 itens do anexo e experimente o preenchimento demonstrativo.'],
 metodologia:['TRANSPARÊNCIA DO PAINEL','Como ler os resultados','Conheça o cálculo, as regras de comparação e os limites desta demonstração.']
};
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const checklistUI={phase:'',answers:{}};
const answerKey=()=>`${ui.uf||'Brasil'}:${ui.cycle}`;
const answers=()=>checklistUI.answers[answerKey()]??={};
const ui={view:'geral',cycle:3,region:'',uf:'',search:'',band:'',rankingMode:'score',auditStatus:''};
const analyticsController=createAnalyticsController({getCycle:()=>ui.cycle,getUF:()=>ui.uf,onUFChange:uf=>{ui.uf=uf;ui.region='';$('#region').value='';updateStateOptions();render();},toast:message=>toast(message)});
let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function filtered(c=ui.cycle){return rowsFor(c).filter(r=>(!ui.region||r.region===ui.region)&&(!ui.uf||r.uf===ui.uf));}
function filteredAudits(){const codes=new Set(filtered().map(r=>r.uf));return auditsFor(ui.cycle).filter(a=>codes.has(a.uf)&&(!ui.auditStatus||a.status===ui.auditStatus));}
function rankingRows(){const q=ui.search.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');return filtered().filter(r=>(!ui.band||band(r.score)===ui.band)&&(!q||`${r.uf} ${r.name} ${r.region}`.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q))).sort((a,b)=>ui.rankingMode==='delta'?b.delta-a.delta||b.score-a.score:b.score-a.score||a.uf.localeCompare(b.uf));}
function bandBadge(s){return `<span class="badge ${bandClass(s)}">${band(s)==='Ouro'?ico('trophy',10):''}${band(s)}</span>`;}
function delta(d){return `<span class="delta ${d>=0?'positive':'negative'}">${d>=0?'↗':'↘'} ${d>=0?'+':''}${fmt(d)} <small>p.p.</small></span>`;}
function ufLink(r){return `<button class="uf-link" data-uf="${r.uf}" aria-label="Ver detalhes de ${r.name}"><span class="uf-badge">${r.uf}</span><span>${r.name}<small>${r.region}</small></span></button>`;}
function kpi(label,value,unit,foot,icon='grid',footClass=''){return `<article class="kpi"><div class="kpi-label">${label}<span class="kpi-icon">${ico(icon,16)}</span></div><div class="kpi-value">${value}<small>${unit}</small></div><div class="kpi-foot ${footClass}">${foot}</div></article>`;}
function statusBadge(s){const c=s==='Concluída'?'green':s==='Planejada'?'gray':s==='Contraditório'?'silver':'blue';return `<span class="badge ${c}">${s}</span>`;}
function panelHead(title,description,extra=''){return `<div class="panel-heading"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${extra}</div>`;}
function heat(v){return `<span class="heat-cell ${v>=85?'heat-high':v>=70?'heat-mid':v>=50?'heat-low':'heat-critical'}">${fmt(v)}</span>`;}
function insight(title,text,view='',label=''){return `<div class="insight-strip">${ico('info',18)}<div><strong>${title}</strong><p>${text}</p></div>${view?`<button class="text-button" data-view="${view}">${label}${ico('arrow',14)}</button>`:''}</div>`;}
function trendChart(values,id='trend',large=false){
 const w=450,h=177,left=35,right=20,top=24,bottom=30,low=20,high=100;
 const x=i=>left+i*(w-left-right)/3,y=n=>top+(high-n)/(high-low)*(h-top-bottom);
 const path=values.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');
 const area=`${path} L${x(3)},${h-bottom} L${left},${h-bottom}Z`;
 return `<div class="trend-chart ${large?'dialog-chart':''}"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolução do IQD: ${values.map((v,i)=>`${cycles[i]}: ${fmt(v)} pontos`).join('; ')}"><defs><linearGradient id="fill-${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#2670d9" stop-opacity=".16"/><stop offset="1" stop-color="#2670d9" stop-opacity=".01"/></linearGradient></defs>${[40,60,80,100].map(v=>`<line class="chart-grid" x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-label" x="${left-9}" y="${y(v)+3}" text-anchor="end">${v}</text>`).join('')}<line class="chart-target" x1="${left}" x2="${w-right}" y1="${y(85)}" y2="${y(85)}"/><path d="${area}" fill="url(#fill-${id})"/><path d="${path}" stroke="#2670d9" fill="none" stroke-width="2.8" stroke-linejoin="round"/>${values.map((v,i)=>`<circle class="chart-point" cx="${x(i)}" cy="${y(v)}" r="${i===ui.cycle?5:3.5}" tabindex="0" role="button" aria-label="Ciclo ${i+1}: ${fmt(v)} pontos" data-trend="Ciclo ${i+1} · ${cycles[i]}: IQD ${fmt(v)}"><title>Ciclo ${i+1} · ${cycles[i]}: ${fmt(v)} pontos</title></circle><text class="chart-label" x="${x(i)}" y="${h-10}" text-anchor="middle">${cycles[i]}</text>`).join('')}<text x="${x(3)-3}" y="${Math.max(14,y(values[3])-13)}" text-anchor="end" font-size="12" font-weight="700" fill="#1351b4">${fmt(values[3])}</text></svg></div>`;
}
function trendPanel(rows){const values=cycles.map((_,c)=>avg(filtered(c),'score'));return `<article class="panel">${panelHead('A evolução é coletiva','IQD médio das UFs selecionadas · quatro ciclos')}<div class="trend-summary"><strong>${fmt(avg(rows,'score'))}</strong>${delta(avg(rows,'delta'))}</div>${trendChart(values)}<div class="chart-legend"><span><i class="legend-line"></i>IQD médio</span><span><i class="legend-line target"></i>Referência Ouro · 85</span></div><div class="dimension-list">${dimensions.map(d=>`<div title="${d.name}"><div class="dimension-label"><span>${d.code} · ${d.short}</span><strong>${fmt(avg(rows,d.key))}%</strong></div><div class="meter"><i style="width:${avg(rows,d.key)}%"></i></div></div>`).join('')}</div><div class="dimension-foot">Média simples entre UFs · pesos: CT 35%, CC 30%, TM 20%, CN 15%.</div></article>`;}
function rankingTable(rows,full=false){return `<div class="table-wrap"><table class="${full?'full-ranking':'overview-ranking'}"><thead><tr><th scope="col" title="Posição nacional pelo IQD-base mensal">Pos.</th><th scope="col">Unidade da Federação</th><th scope="col">IQD-base</th>${full?dimensions.map(d=>`<th scope="col" title="${esc(d.name)}">${d.code}</th>`).join(''):''}<th scope="col">Faixa-base</th><th scope="col">Evolução¹</th>${full?'<th scope="col" title="Cobertura efetiva de volume, separada do CT 35%">CE²</th><th scope="col">Modalidade fictícia</th><th scope="col">Bônus PPE/API</th><th scope="col">Acompanhamento</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td class="rank ${r.rank<=3?'top-rank':''}">${String(r.rank).padStart(2,'0')}º</td><td>${ufLink(r)}</td><td class="score-cell">${fmt(r.score,2)}${full?'':`<span class="score-bar"><i style="width:${r.score}%"></i></span>`}</td>${full?dimensions.map(d=>`<td>${heat(r[d.key])}</td>`).join(''):''}<td>${bandBadge(r.score)}</td><td>${delta(r.delta)}</td>${full?`<td>${fmt(r.ce)}%</td><td>${r.modality.name}<small class="delivery-latency">${latency(r.latencyHours)} · mediana simulada</small></td><td><span class="badge gray">A pactuar</span><small class="delivery-latency">Não aplicado à nota</small></td><td>${needsPlan(r)?'<span class="badge blue">PAI simulado</span>':'<span class="badge gray">Rotina</span>'}</td>`:''}</tr>`).join('')||`<tr><td colspan="${full?13:6}" class="empty-state">Nenhuma UF encontrada. Ajuste a busca ou limpe os filtros.</td></tr>`}</tbody></table></div>`;}
function bandPanel(rows){const bands=['Ouro','Prata','Bronze','Crítico'];return `<article class="panel">${panelHead('Um retrato do desempenho','Classificação de qualidade · sem efeito financeiro automático')}<div class="band-distribution" aria-hidden="true">${bands.map(b=>`<span class="${bandClass(({Ouro:90,Prata:75,Bronze:60,'Crítico':40})[b])}" style="flex:${rows.filter(r=>band(r.score)===b).length||'.001'}"></span>`).join('')}</div><div class="band-items">${bands.map(b=>`<button class="band-item" data-band="${b}" aria-label="Ver ${b} no ranking"><span class="count">${rows.filter(r=>band(r.score)===b).length}</span>${bandBadge(({Ouro:90,Prata:75,Bronze:60,'Crítico':40})[b])}</button>`).join('')}</div><div class="territory">${['Norte','Nordeste','Centro-Oeste','Sudeste','Sul'].map(reg=>{const rr=rows.filter(r=>r.region===reg);return rr.length?`<div class="territory-group"><div class="mini-label">${reg.toUpperCase()}</div><div class="territory-tiles">${rr.sort((a,b)=>a.uf.localeCompare(b.uf)).map(r=>`<button class="uf-tile ${bandClass(r.score)}" data-uf="${r.uf}" title="${r.name}: ${fmt(r.score)} · ${band(r.score)}" aria-label="${r.name}: ${fmt(r.score)} pontos, faixa ${band(r.score)}">${r.uf}</button>`).join('')}</div></div>`:'';}).join('')}</div></article>`;}
function auditSummaryPanel(rows){const codes=new Set(rows.map(r=>r.uf));const aa=auditsFor(ui.cycle).filter(a=>codes.has(a.uf));const total=aa.length,closed=aa.filter(a=>a.status==='Concluída').length,planned=aa.filter(a=>a.status==='Planejada').length,progress=total-closed-planned;const cp=percent(closed,total),pp=cp+percent(progress,total);return `<article class="panel">${panelHead('Auditoria que gera melhoria','Verificações técnicas previstas neste quadrimestre')}<div class="audit-summary"><div class="donut" style="background:conic-gradient(#16815b 0 ${cp}%,#2670d9 ${cp}% ${pp}%,#e9eef5 ${pp}% 100%)"><div class="donut-center"><strong>${total}</strong><span>verificações</span></div></div><div class="audit-legend"><div class="audit-legend-row"><i class="legend-dot" style="background:#16815b"></i>Concluídas<strong>${closed}</strong></div><div class="audit-legend-row"><i class="legend-dot" style="background:#2670d9"></i>Em andamento<strong>${progress}</strong></div><div class="audit-legend-row"><i class="legend-dot" style="background:#d4deec"></i>Planejadas<strong>${planned}</strong></div></div></div><div class="panel-footer"><span>${rows.filter(needsPlan).length} UFs com PAI simulado</span><button class="text-button" data-view="auditorias">Acompanhar planos ${ico('arrow',13)}</button></div></article>`;}
function overview(){const rows=filtered();const all=rows.filter(r=>r.score>=70).length;const quality=avg(rows,'score');const audits=auditsFor(ui.cycle).filter(a=>rows.some(r=>r.uf===a.uf));return `<section class="kpi-grid" aria-label="Indicadores do ciclo">${kpi('IQD médio das UFs',fmt(quality),'/ 100',`${ico('trend',12)} +${fmt(avg(rows,'delta'))} p.p. desde D+30`,'trend','positive')}${kpi('Entes acompanhados',rows.length,'UFs',`${ico('globe',12)} ${new Set(rows.map(r=>r.region)).size} regiões no recorte`,'globe')}${kpi('Faixas Ouro e Prata',all,`/ ${rows.length}`,`${fmt(percent(all,rows.length),0)}% das UFs com IQD ≥ 70`,'trophy')}${kpi('Verificações concluídas',audits.filter(a=>a.status==='Concluída').length,`/ ${audits.length}`,`Escopo selecionado por risco e rodízio`,'shield')}</section><section class="section-grid"><article class="panel">${panelHead('Quem está puxando a qualidade','Posições nacionais · dados de demonstração',`<div class="toggle-group" aria-label="Ordenar destaques"><button data-order="score" class="${ui.rankingMode==='score'?'active':''}">Desempenho</button><button data-order="delta" class="${ui.rankingMode==='delta'?'active':''}">Evolução</button></div>`)}${rankingTable([...rows].sort((a,b)=>ui.rankingMode==='delta'?b.delta-a.delta:b.score-a.score).slice(0,6))}<div class="panel-footer"><span>¹ Variação do IQD desde o ciclo D+30.</span><button class="text-button" data-view="ranking">Ver ranking completo ${ico('arrow',13)}</button></div></article>${trendPanel(rows)}</section><section class="section-grid equal">${bandPanel(rows)}${auditSummaryPanel(rows)}</section>${insight('Reconhecer avanços também mobiliza a rede.','Desempenho, evolução e cooperação têm visibilidade própria. O IQD mede qualidade do dado; participação e retorno ao ente completam a análise.','participacao','Explorar participação')}`;}
function ranking(){const rows=rankingRows();return `${insight('A nota segue os entregáveis finais.','CT 35%, CC 30%, TM 20% e CN 15%. TM usa a janela de 24 horas da lavratura; CE continua visível como indicador complementar de volume. O bônus pelo uso efetivo de PPE/API aguarda regra e limite no Consinesp, por isso ainda não altera o ranking.')}<article class="panel wide-panel">${panelHead('Ranking dos estados e do Distrito Federal','IQD-base mensal, sem bônus de adoção. Abra uma UF para conferir os denominadores.',`<span class="badge blue">${filtered().length} UFs no recorte</span>`)}<div class="table-controls"><div class="search-box">${ico('search',15)}<input id="ranking-search" aria-label="Buscar UF, estado ou região" placeholder="Buscar UF, estado ou região" value="${esc(ui.search)}"></div><select class="compact-select" id="band-filter" aria-label="Filtrar faixa de qualidade"><option value="">Todas as faixas</option>${['Ouro','Prata','Bronze','Crítico'].map(b=>`<option ${ui.band===b?'selected':''}>${b}</option>`).join('')}</select><select class="compact-select" id="ranking-order" aria-label="Ordenar ranking"><option value="score" ${ui.rankingMode==='score'?'selected':''}>Maior IQD-base</option><option value="delta" ${ui.rankingMode==='delta'?'selected':''}>Maior evolução</option></select><span class="table-note">Base de 0 a 100 · bônus a pactuar</span></div><div id="ranking-table">${rankingTable(rows,true)}</div><div class="panel-footer"><span id="ranking-count">${rows.length} UFs exibidas · ¹ Evolução desde D+30.</span><button class="text-button" data-view="metodologia">Como calculamos ${ico('arrow',13)}</button></div></article><div class="ranking-method-note">² CE = BOs recepcionados / BOs lavrados × 100. CT = delegacias com envio diário / total de delegacias × 100. As duas coberturas são distintas. Modalidades, notas, latências e adesões são fictícias. O selo exibido é a faixa da nota-base, sujeita à validação e homologação previstas na proposta.</div><section class="section-grid equal">${bandPanel(filtered())}${trendPanel(filtered())}</section>`;}
function auditTable(aa){return `<div class="table-wrap"><table><thead><tr><th>Verificação / UF</th><th>Seleção</th><th>Etapa atual</th><th>Responsável</th><th>Marco previsto²</th><th>Evidências</th><th><span class="sr-only">Detalhes</span></th></tr></thead><tbody>${aa.map(a=>`<tr><td><button class="uf-link" data-uf="${a.uf}"><span class="uf-badge">${a.uf}</span><span>${a.id}<small>${states.find(r=>r.uf===a.uf).name}</small></span></button></td><td>${a.type}</td><td>${statusBadge(a.status)}</td><td>${a.owner}<small style="display:block;font-size:8px;color:#7c8fa8">Revisão: ${a.reviewer}</small></td><td>${a.status==='Concluída'?'<span class="positive">Concluído</span>':`D+${a.deadline}${a.late?' <span class="badge bronze">Reprogramar</span>':''}`}</td><td class="progress-cell"><span class="meter"><i style="width:${percent(a.finished,a.total)}%"></i></span>${a.finished}/${a.total}</td><td><button class="table-action" data-audit="${a.id}" aria-label="Detalhar ${a.id}" aria-expanded="false">${ico('arrow',15)}</button></td></tr><tr class="audit-row-details" id="${a.id}" hidden><td colspan="7" class="audit-detail"><strong>${a.phase}.</strong> ${a.selection}<br>Universo demonstrativo: ${integer(a.universe)} BOs; amostra dirigida prevista: ${integer(a.sample)} BOs. ${a.findings} achados registrados; ${a.critical} de prioridade alta.<br><strong>Como verificar:</strong> conciliação da coorte local e nacional; reexecução das regras de qualidade; exame de trilhas e dos perfis autorizados. A manifestação da UF e a revisão técnica integram o relatório.<br><strong>Quem acompanha:</strong> DGI coordena e decide no âmbito técnico; UF apresenta evidências e corrige; Serpro fornece suporte contratado. Logs individuais não são publicados.</td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">Nenhuma verificação neste recorte. A UF permanece no monitoramento de rotina.</td></tr>'}</tbody></table></div>`;}
function plansTable(plans){return `<div class="table-wrap"><table><thead><tr><th>UF</th><th>Foco da melhoria</th><th>Execução das ações</th><th>Responsáveis</th><th>Próxima revisão²</th><th>Situação</th></tr></thead><tbody>${plans.map(p=>`<tr><td><button class="uf-link" data-uf="${p.uf}"><span class="uf-badge">${p.uf}</span>${states.find(s=>s.uf===p.uf).name}</button></td><td>${p.cause}</td><td class="progress-cell"><span class="meter"><i style="width:${p.progress}%"></i></span>${p.completed}/${p.total}</td><td>${p.owner}<small style="display:block;font-size:8px;color:#7c8fa8">${p.federal}</small></td><td>${p.due}</td><td><span class="badge ${p.status==='Prazo em revisão'?'bronze':'blue'}">${p.status}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty-state">Nenhum PAI ativo neste recorte. O monitoramento de rotina continua.</td></tr>'}</tbody></table></div>`;}
function auditPage(){const rows=filtered(),codes=new Set(rows.map(r=>r.uf)),aa=auditsFor(ui.cycle).filter(a=>codes.has(a.uf)),plans=plansFor(ui.cycle).filter(a=>codes.has(a.uf));const done=aa.filter(a=>a.status==='Concluída').length;return `<section class="kpi-grid">${kpi('Verificações programadas',aa.length,'',`${rows.length-aa.length} UFs em monitoramento`,'shield')}${kpi('Verificações concluídas',done,`/ ${aa.length}`,`${integer(percent(done,aa.length))}% do plano demonstrativo`,'check')}${kpi('Planos acompanhados',plans.length,'PAIs',`Gatilhos confirmados na simulação`,'file')}${kpi('Itens do checklist',21,'itens',`5 fases do anexo final`,'book')}</section><article class="panel wide-panel">${panelHead('Protocolo do auditor','Cinco passos do Manual de Auditabilidade; a programação das inspeções depende do escopo e do risco.')}<div class="workflow">${checklistContent.protocolo.map(s=>`<div class="workflow-step"><span class="step-number">${s.id}</span><strong>${esc(s.titulo)}</strong><p>${esc(s.descricao)}</p></div>`).join('')}</div><div class="panel-footer"><span>IQD mensal · revisão trimestral no Consinesp · extrato e selos quadrimestrais. Não há frequência universal de inspeção por UF fixada pelos entregáveis.</span><button class="text-button" data-view="checklist">Abrir checklist ${ico('arrow',13)}</button></div></article><article class="panel wide-panel">${panelHead('Agenda de verificações técnicas','Plano fictício de 12 UFs; acompanhar 27 entes não significa auditar integralmente os 27.',`<span class="badge gray">1º quadrimestre simulado</span>`)}<div class="table-controls"><div class="chips" aria-label="Filtrar etapa da verificação">${['','Planejada','Em execução','Contraditório','Concluída'].map(s=>`<button class="chip ${ui.auditStatus===s?'active':''}" data-audit-status="${s}" aria-pressed="${ui.auditStatus===s}">${s||'Todas as etapas'}</button>`).join('')}</div></div>${auditTable(filteredAudits())}<div class="panel-footer"><span>Marcos D+ são datas demonstrativas de gestão; as evidências usam os 21 itens do checklist.</span></div></article><article class="panel wide-panel">${panelHead('Plano de Aprimoramento Individualizado · PAI','Assistência, causas, responsáveis e acompanhamento. A nota não executa sanção.',`<span class="badge blue">${plans.length} em acompanhamento</span>`)}${plansTable(plans)}<div class="panel-footer"><span>A Nota 2.5 usa IQD&lt;70 no quadrimestre; o quadro de gatilhos e o checklist usam IQD&lt;60 em dois quadrimestres. Consulte as janelas na metodologia.</span><button class="text-button" data-view="metodologia">Ver critérios ${ico('arrow',13)}</button></div></article><section class="section-grid equal"><article class="panel">${panelHead('Gatilhos observados neste mês','Cada teste utiliza sua própria série, sem deduzir latência de 72h a partir de TM24h.')}<div class="bar-chart">${[['CT abaixo de 80%',r=>r.ct<80],['Campos nulos acima de 30%',r=>r.nullFieldsPct>30],['Mais de 25% dos BOs acima de 72h',r=>r.late72Pct>25],['Rejeição de carga acima de 15%',r=>r.rejectionPct>15]].map(([name,test])=>{const n=rows.filter(test).length;return `<div class="bar-row"><div class="bar-row-label"><span>${name}</span><strong>${n} UFs</strong></div><div class="meter"><i style="width:${percent(n,rows.length)}%"></i></div></div>`}).join('')}</div></article><article class="panel">${panelHead('Responsáveis no modelo proposto','Papéis dos entregáveis finais, com contraditório e decisão formal.')}<div class="role-list">${[['shield','DGI / Senasp','Aferição mensal, painel, programação de auditoria e apoio técnico.'],['people','Consinesp e entes','Homologação do IQD e pactuação; UFs fornecem dados e executam correções.'],['layers','Serpro e DPO','Suporte de infraestrutura; participação do encarregado em acesso, segurança e proteção de dados.'],['book','Controle e decisão','TCU e TCEs fiscalizam em seu âmbito. A proposta reserva a suspensão financeira a processo e ato do Ministro.']].map(r=>`<div class="role"><span class="role-icon">${ico(r[0],16)}</span><div><strong>${r[1]}</strong><p>${r[2]}</p></div></div>`).join('')}</div></article></section>`;}
function participation(){const rows=filtered(),commitRate=percent(sum(rows,'completedCommitments'),sum(rows,'commitments')),returns=percent(sum(rows,'returned'),sum(rows,'requests'));const movers=[...rows].sort((a,b)=>b.delta-a.delta||b.score-a.score).slice(0,5);const cooperators=[...rows].sort((a,b)=>b.practices-a.practices||b.attendance-a.attendance).slice(0,5);const inQuality=rows.filter(r=>r.score>=85).length,active=rows.filter(r=>r.score>=70&&r.score<85).length,improve=rows.filter(r=>r.score<70).length;return `<section class="kpi-grid">${kpi('Evolução média do IQD',`+${fmt(avg(rows,'delta'))}`,'p.p.',`Comparação com o primeiro ciclo D+30`,'trend','positive')}${kpi('Compromissos executados',fmt(commitRate,0),'%',`${sum(rows,'completedCommitments')} de ${sum(rows,'commitments')} entregas pactuadas`,'check')}${kpi('Presença dos pontos focais',fmt(avg(rows,'attendance'),0),'%',`Média de participação nas agendas do ciclo`,'people')}${kpi('Demandas com devolutiva',fmt(returns,0),'%',`${sum(rows,'returned')} de ${sum(rows,'requests')} demandas respondidas`,'link')}</section><section class="section-grid equal"><article class="panel">${panelHead('Toda evolução merece visibilidade','Maiores avanços desde D+30 · resultado separado do selo IQD',`<span class="badge green">Evolução</span>`)}${movers.map(r=>`<div class="participation-row">${ufLink(r)}<div class="participation-body"></div>${delta(r.delta)}</div>`).join('')}<div class="participation-note">A comparação em pontos do índice reconhece o avanço dos entes com condições iniciais distintas. Não há bonificação automática na nota do IQD.</div></article><article class="panel">${panelHead('Conhecimento que circula','Práticas compartilhadas e registradas no ciclo simulado',`<span class="badge blue">Cooperação</span>`)}${cooperators.map(r=>`<div class="participation-row">${ufLink(r)}<div class="participation-body"></div><div style="text-align:right"><strong>${r.practices}</strong><p>práticas compartilhadas</p></div></div>`).join('')}<div class="participation-note">Contagem demonstrativa de compartilhamento. A adoção e a utilidade das práticas precisam de evidência própria; não compõem o IQD.</div></article></section>${rolloutPanel()}<section class="section-grid equal"><article class="panel">${panelHead('Retorno concreto para quem participa','Serviços e suporte como parte do compromisso federativo')}<div class="bar-chart">${[['Devolutiva das demandas',returns],['Execução dos compromissos',commitRate],['Participação nas agendas',avg(rows,'attendance')],['Cobertura operacional das unidades · CT',avg(rows,'ct')]].map(([n,v])=>`<div class="bar-row"><div class="bar-row-label"><span>${n}</span><strong>${fmt(v,0)}%</strong></div><div class="meter"><i style="width:${v}%"></i></div></div>`).join('')}</div><div class="panel-footer"><span>Uso agregado dos serviços no ciclo: ${integer(sum(rows,'uses'))} interações simuladas.</span></div></article><article class="panel">${panelHead('A rede aprende e melhora','Exemplos fictícios de práticas para intercâmbio')}<div class="cooperation-card">${[['layers','Conciliação da mesma coorte','Guia de deduplicação de BOs e conferência dos denominadores.','CE · Cobertura de envio'],['clock','Transmissão em até 24 horas','Análise da tempestividade e dos registros com latência superior a 72 horas.','TM · Tempestividade 24h'],['people','Oficina entre pontos focais','Compartilhamento de regras e tratamento das dúvidas recorrentes.','Cooperação · Aprendizado entre entes']].map(p=>`<div class="practice"><div class="practice-icon">${ico(p[0],18)}</div><div><strong>${p[1]}</strong><p>${p[2]}</p><span class="small-link">${p[3]}</span></div></div>`).join('')}</div></article></section>${insight('Qualidade é um compromisso de duas vias.','O ente recebe devolutivas, apoio e serviços dentro das autorizações vigentes. O painel acompanha também as entregas federais, sem prometer novos acessos automáticos às bases.','auditorias','Ver planos de melhoria')}`;}
function methodology(){return `<div class="methodology"><article class="panel"><div class="method-intro">${ico('info',24)}<div><h2>Regras dos entregáveis finais</h2><p>Simulação acadêmica SUSPeritos, compatibilizada com a Nota Técnica final, o Manual com checklist e a apresentação de 22/10/2026. As 27 UFs têm nomes reais e valores inteiramente fictícios. Nenhuma pontuação descreve desempenho real ou situação jurídica de um ente.</p></div></div><div class="formula">IQD-base = 0,35 × CT + 0,30 × CC + 0,20 × TM + 0,15 × CN<small>Base de 0 a 100 · bônus PPE/API previsto, com regra e limite a pactuar</small></div><div class="method-components">${dimensions.map(d=>`<div class="method-component"><strong>${d.code} · ${d.name} <span class="badge blue">${d.weight}%</span></strong><p>${d.definition}</p></div>`).join('')}</div><div class="method-section"><h3>CT e CE medem coberturas diferentes</h3><p>CT é territorial: delegacias com envio diário / total de delegacias. Esse é o componente de 35% da fórmula final. CE é volumétrica: BOs recepcionados / BOs lavrados no período. CE permanece no ranking, nos detalhes e no checklist, com referência de 98% no item 2.2, mas não substitui CT no IQD.</p><p>A simulação calcula cada percentual a partir de numeradores e denominadores. Completude usa campos críticos válidos e aplicáveis; consistência usa registros conformes no universo avaliado. Dados inferidos por IA só são tratados como válidos após supervisão humana no cenário, sem bonificação automática por volume de extração.</p></div><div class="method-section"><h3>TM em até 24 horas</h3><p>A Nota Técnica, seção 2.4, e o slide 12 medem os registros transmitidos em até 24h da lavratura. Essa foi a regra escolhida pelo grupo para esta versão do site. O cenário usa BOs recebidos dentro de 24h / BOs recebidos do mesmo período. Registros ausentes permanecem evidenciados na CE. A regra é a mesma para as modalidades admitidas; não há calendário diferenciado nem fator de desconto fixo pelo canal.</p><p>A modalidade e a mediana de latência continuam visíveis para análise. O gatilho de latência acima de 72h tem numerador próprio e janela de 30 dias; ele não equivale automaticamente ao percentual fora de 24h. Os modos atribuídos às UFs são fictícios, sem informar adesão real ao PPE ou uso real de APIs.</p></div><div class="method-section"><h3>Bônus de adoção ainda a pactuar</h3><p>A apresentação final prevê bônus pelo uso efetivo do Sinesp-PPE e das APIs existentes. Sua regra e seu limite serão pactuados no Consinesp. A Nota não fornece percentual numérico para essa bonificação. O painel, portanto, exibe a nota-base e o status “A pactuar”; não atribui pontos ou multiplicador à modalidade nem calcula uma segunda pontuação.</p><p>PPE e API têm o mesmo tratamento. Arquivo/base e coleta assistida continuam admitidos no cenário. Assinatura de termo, número de chamadas à API e canal isolado não produzem bônus numérico nesta versão.</p></div><div class="method-section"><h3>Selos e indução financeira proposta</h3><p>Ouro: 85 a 100; Prata: 70 a menos de 85; Bronze: 50 a menos de 70; Crítico: abaixo de 50. O ranking usa a nota-base mensal. A classificação visual antecipa a faixa, enquanto a proposta prevê homologação e extrato quadrimestral para reconhecimento formal.</p><div class="table-wrap"><table><thead><tr><th>Faixa</th><th>Fator FNSP proposto</th><th>Tratamento nos entregáveis</th></tr></thead><tbody><tr><td>Ouro</td><td>1,2</td><td>Bonificação e prioridade em convênios na proposta.</td></tr><tr><td>Prata</td><td>1,0</td><td>Recebimento padrão e capacitação.</td></tr><tr><td>Bronze</td><td>0,85</td><td>Ajuste e PAI com apoio técnico.</td></tr><tr><td>Crítico</td><td>Sem fator numérico</td><td>Notificação e eventual processo após persistência.</td></tr></tbody></table></div><p>Esses fatores financeiros são propostas dos documentos, distintos do bônus de adoção PPE/API. Não são aplicados a valores de repasse neste protótipo, não demonstram regra financeira já vigente e não executam suspensão ou prioridade em convênio. Encaminhamentos dependem de análise, pactuação, rito e decisão competentes.</p></div><div class="method-section"><h3>PAI e janelas de acompanhamento</h3><p>Os entregáveis registram critérios diferentes, mantidos visíveis para não substituí-los silenciosamente:</p><ul><li>Nota Técnica 2.5 e slide 14: IQD abaixo de 70 no quadrimestre para PAI e socorro técnico.</li><li>Quadro de gatilhos, checklist 5.2 e slide 14: IQD abaixo de 60 em dois quadrimestres consecutivos.</li><li>Protocolo do Manual, etapa 4: IQD abaixo de 60 ou omissão de delegacias, sem explicitar a janela.</li><li>Outros gatilhos: menos de 80% das delegacias enviando; nulos acima de 30% na carga mensal; latência acima de 72h em mais de 25% dos registros por 30 dias; rejeição de carga acima de 15%.</li></ul><p>Neste cenário, o acompanhamento é aberto por gatilho operacional confirmado ou por IQD quadrimestral abaixo de 70 no fechamento D+120. A regra de dois quadrimestres não é aferida: a demonstração tem apenas um quadrimestre de histórico. O critério sem janela do protocolo permanece como ponto de conferência. A notificação por dois meses abaixo da meta depende da meta pactuada, não quantificada como um limiar único nos entregáveis.</p><p>O IQD quadrimestral mostrado é calculado sobre os numeradores e denominadores acumulados dos quatro meses, e pode diferir da nota mensal D+120. A abertura ou execução de PAI simulado não declara inadimplência legal. A proposta situa sanções após notificação, assistência e processo formal, sem bloqueio financeiro automático pelo painel.</p></div><div class="method-section"><h3>Quem verifica e com qual instrumento</h3><p>O Manual estabelece sete etapas, cinco passos do auditor e 21 itens do checklist, reproduzidos na seção própria. As auditorias ordinárias, extraordinárias e de PAI dependem de escopo e programação; os entregáveis não impõem inspeção integral de todas as UFs a cada quadrimestre. O plano desta demonstração seleciona 12 verificações.</p><ul><li>Diariamente: declaração de BOs e acompanhamento de transmissão.</li><li>Mensalmente: aferição do IQD e atualização do painel.</li><li>Trimestralmente: revisão de prioridades no Consinesp.</li><li>Quadrimestralmente: extrato de adimplência, selos e avaliação dos gatilhos do PAI.</li><li>Em cada inspeção: planejamento, ingestão, acesso e uso, achados com manifestação do ente e monitoramento com encaminhamentos.</li></ul><p>DGI/Senasp coordena a medição e as equipes; UFs e pontos focais fornecem evidências e executam correções; Serpro presta suporte; Consinesp participa da homologação e pactuação previstas na proposta. O controle interno e externo atua em suas competências. Logs individuais, CPF, nomes de usuários e dados operacionais protegidos não são publicados.</p></div><div class="method-section"><h3>Ondas de implantação</h3><ul><li>Onda 1, 0 a 120 dias: medir e cumprir, linha de base, painel público, canal de demandas e pontos focais.</li><li>Onda 2, 3 a 12 meses: pactuar IQD, revisar regras, incentivos do FNSP e capacidade institucional.</li><li>Onda 3, 12 a 36 meses: consolidar e expandir, metadados de inquéritos e laudos, estatísticas da BNBO e PAIs consolidados.</li></ul><p>Os quatro ciclos D+30 a D+120 representam somente a Onda 1. A agenda de 90 dias do painel é apresentada como marco dos entregáveis; a simulação não certifica cumprimento real de deliberação do TCU.</p></div><div class="method-section"><h3>Comparação e participação</h3><p>Posições nacionais são calculadas pela nota-base, com desempate alfabético da sigla. Os filtros preservam essa posição. Evolução é a diferença em pontos do IQD desde D+30. A média é aritmética entre UFs, sem ponderação por população ou volume. Participação, práticas, demandas respondidas e compromissos são indicadores separados; não criam peso novo no IQD.</p><p>Os quatro pontos do gráfico representam cenários mensais da mesma implantação hipotética. Valores futuros da simulação permanecem visíveis ao selecionar ciclo anterior. Em operação real, ausência de evidência ou denominador exige resultado não aferido, sem nota presumida.</p></div><div class="method-section"><h3>Fontes e versão da compatibilização</h3><ul><li>Nota Técnica final SUSPeritos: seções 2.4,2.5 e matrizes de governança, arquivo atualizado em 20/10/2026.</li><li>Protótipo de Auditabilidade e Anexo de Checklist: sete etapas, cinco passos e 21 itens, versão de 20/10/2026.</li><li>Apresentação final: slides 7 a 16, arquivo atualizado em 22/10/2026.</li><li><a href="https://www.gov.br/ds/home" target="_blank" rel="noopener">Design System gov.br</a> e <a href="https://www.gov.br/conecta/catalogo/" target="_blank" rel="noopener">Catálogo Conecta</a>: referências de identidade, busca e filtros, sem conexão com bases oficiais.</li></ul><p>Compatibilização de 22/10/2026. Regras acadêmicas propostas e dados inteiramente fictícios; este painel não é publicação oficial do MJSP.</p></div></article></div>`;}
function rolloutPanel(){return `<article class="panel wide-panel">${panelHead('Implementação em três ondas','Roteiro dos entregáveis finais. O cenário de D+30 a D+120 acompanha a primeira onda.')}<div class="rollout-grid">${[['1','0 a 120 dias','Medir e cumprir','Linha de base, declaração de BOs, Painel Público em 90 dias, canal de demandas e pontos focais.','Em implantação'],['2','3 a 12 meses','Alinhar regras e incentivos','Pactuação do IQD, revisão das regras, incentivos do FNSP e capacidade da DGI.','Planejada'],['3','12 a 36 meses','Consolidar e expandir','Inquéritos e laudos, estatísticas da BNBO e consolidação dos PAIs.','Planejada']].map(w=>`<div class="rollout-wave"><span class="badge ${w[0]==='1'?'blue':'gray'}">Onda ${w[0]} · ${w[1]}</span><h3>${w[2]}</h3><p>${w[3]}</p><strong>${w[4]}</strong></div>`).join('')}</div></article>`;}
function checklistPage(){const current=answers(),answered=Object.values(current).filter(a=>a.result&&a.result!=='Não aferido').length,conform=Object.values(current).filter(a=>a.result==='Conforme').length;return `<section class="kpi-grid">${kpi('Itens do anexo',21,'itens','Texto dos entregáveis finais','book')}${kpi('Fases do checklist',5,'fases','Preparação à consolidação','layers')}${kpi('Itens aferidos',answered,'/21','Preenchimento temporário desta sessão','check')}${kpi('Itens conformes',conform,'',`Escopo:${ui.uf||'Brasil'} · ${cycles[ui.cycle]}`,'shield')}</section>${insight('Formulário demonstrativo do anexo final.','Ações e critérios preservam o manual recebido. As respostas ficam somente na sessão aberta do navegador e podem ser exportadas em CSV; não são enviadas a órgão público nem alteram as pontuações fictícias.')}<article class="panel wide-panel">${panelHead('Checklist operacional do auditor','Resultado, referência da evidência e observações técnicas por item.')}<div class="table-controls"><select id="checklist-phase" class="compact-select" aria-label="Filtrar fase do checklist"><option value="">Todas as fases</option>${checklistContent.fases.map(f=>`<option value="${f.id}" ${checklistUI.phase===String(f.id)?'selected':''}>${esc(f.titulo)}</option>`).join('')}</select><button class="text-button" data-clear-checklist>Limpar preenchimento deste recorte</button></div><div class="checklist-groups">${checklistContent.fases.filter(f=>!checklistUI.phase||String(f.id)===checklistUI.phase).map(f=>`<section class="checklist-phase"><h3>${esc(f.titulo)}</h3>${checklistContent.itens.filter(i=>i.fase===f.id).map(i=>{const answer=current[i.id]||{};return `<details class="checklist-item" ${checklistUI.phase?'open':''}><summary><span class="checklist-id">${i.id}</span>${esc(i.titulo)}<span class="badge gray">${esc(answer.result||'Não aferido')}</span></summary><div class="checklist-item-body"><p><strong>Ação de verificação</strong>${esc(i.acao)}</p><p><strong>Critério de conformidade</strong>${esc(i.criterio)}</p><div class="checklist-fields"><label for="result-${i.id}">Resultado<select id="result-${i.id}" data-check-result="${i.id}">${checklistContent.opcoes_resultado.map(s=>`<option ${s===(answer.result||'Não aferido')?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label for="evidence-${i.id}">Evidência / observações<textarea id="evidence-${i.id}" data-check-note="${i.id}" rows="2" placeholder="Referência da evidência ou observação técnica">${esc(answer.note||'')}</textarea></label></div></div></details>`}).join('')}</section>`).join('')}</div><div class="panel-footer"><span>21 critérios documentais. O resultado do formulário não substitui a auditoria, a manifestação do ente ou a decisão competente.</span><button class="text-button" data-view="auditorias">Voltar à auditoria ${ico('arrow',13)}</button></div></article><article class="panel wide-panel">${panelHead('Sete etapas e responsáveis','Processo do Manual de Auditabilidade. Os textos abaixo descrevem o modelo proposto.')}<div class="process-list">${checklistContent.processo.map(s=>`<details><summary>${s.id}. ${esc(s.titulo)}</summary><p>${esc(s.acao)}</p><p><strong>Responsáveis:</strong> ${esc(s.responsaveis)}</p><p class="source-note">${esc(s.fundamento)}</p></details>`).join('')}</div></article>`;}

function updateStateOptions(){const list=states.filter(s=>!ui.region||s.region===ui.region).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));$('#state').innerHTML='<option value="">Todas as UFs</option>'+list.map(s=>`<option value="${s.uf}" ${ui.uf===s.uf?'selected':''}>${s.uf} · ${s.name}</option>`).join('');}
function render(){
 if(ui.view==='analitico'&&ui.region){ui.region='';$('#region').value='';updateStateOptions();}
 $('#region').disabled=ui.view==='analitico';
 $('#region').title=ui.view==='analitico'?'Use a UF e os filtros territoriais da análise detalhada.':'';
 const [eye,title,description]=headings[ui.view];$('#page-eyebrow').textContent=eye;$('#page-title').textContent=title;$('#page-description').textContent=description;
 $('#navigation').innerHTML=navs.map(([view,label,icon])=>`<button class="nav-button ${ui.view===view?'active':''}" data-view="${view}" ${ui.view===view?'aria-current="page"':''}>${ico(icon,17)}${label}${view==='ranking'?'<span class="nav-count">27</span>':''}</button>`).join('');
 $('#breadcrumb-current').textContent=navs.find(n=>n[0]===ui.view)[1];
 $('#cutoff-label').innerHTML=`${ui.cycle===3?'Fechamento':'Marco'} simulado<br><strong>${cycles[ui.cycle]} da implantação</strong>`;
 $('#filter-summary').innerHTML=`<span><strong>${ui.uf?states.find(s=>s.uf===ui.uf).name:ui.region||'Brasil'}</strong> · ${filtered().length} ${filtered().length===1?'UF acompanhada':'UFs acompanhadas'}</span><span class="cycle-tag">${ico('clock',11)} Ciclo ${ui.cycle+1} de 4 · ${ui.cycle===3?'1º quadrimestre concluído':'acompanhamento em curso'}</span>`;
 $('#export').innerHTML=`${ico('download',15)} Exportar dados`;
 $('#export').hidden=ui.view==='metodologia';
 if(ui.view==='analitico')analyticsController.render($('#content'));
 else $('#content').innerHTML=({geral:overview,ranking, auditorias:auditPage,participacao:participation,checklist:checklistPage,metodologia:methodology})[ui.view]();
}
function go(view){if(!headings[view])return;ui.view=view;$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'',`#${view}`);}
function showUF(code){const row=rowsFor(ui.cycle).find(r=>r.uf===code),p=plansFor(ui.cycle).find(p=>p.uf===code),audit=auditsFor(ui.cycle).find(a=>a.uf===code);if(!row)return;const fiscal=fiscalProposal(row.score);$('#uf-dialog-content').innerHTML=`<div class="dialog-header"><div class="uf-cell"><span class="uf-badge">${row.uf}</span><div><h2 id="uf-dialog-title">${row.name}</h2><p>${row.region} · Ciclo${ui.cycle+1} · ${cycles[ui.cycle]}</p></div></div><button class="icon-button" data-close-dialog aria-label="Fechar detalhes">${ico('close',20)}</button></div><div class="dialog-body"><div class="dialog-warning"><strong>Dados inteiramente fictícios.</strong> Não representam o desempenho real de${row.name}.</div><div class="dialog-score"><div><small>IQD-base mensal · ${row.rank}ª posição nacional</small><div class="big-score">${fmt(row.score,2)} <small>/100</small></div>${bandBadge(row.score)}</div><div>${delta(row.delta)}<br><small>desde D+30</small></div></div>${trendChart(row.history.map(h=>h.score),`uf-${row.uf}`,true)}<div class="dialog-dimensions">${dimensions.map(d=>`<div title="${esc(d.definition)}"><div class="dimension-label"><span>${d.code} · ${d.short}</span><strong>${fmt(row[d.key])}%</strong></div><div class="meter"><i style="width:${row[d.key]}%"></i></div></div>`).join('')}</div><div class="dialog-meta"><span>CT:${row.dailyUnits}/${row.totalUnits} delegacias</span><span>CE:${fmt(row.ce)}% · ${integer(row.receivedBO)}/${integer(row.localBO)} BOs</span><span>TM24h:${integer(row.timelyBO)}/${integer(row.receivedBO)} BOs recebidos</span></div><h3 class="dialog-section-title">Modalidade e bônus de adoção</h3><div class="dialog-plan"><strong>${row.modality.name} · canal fictício</strong>Mediana de latência:${latency(row.latencyHours)}. A TM usa24 horas desde a lavratura em todas as modalidades.<br><strong>Bônus PPE/API a pactuar</strong>Regra e limite pendentes de pactuação no Consinesp. Não há bônus aplicado ou pontuação adicional calculada.<br>Fator FNSP proposto para a faixa:${fiscal.factor===null?'sem fator numérico':fmt(fiscal.factor,2)}. É proposta de indução financeira, não bônus de adoção nem repasse executado.</div><h3 class="dialog-section-title">Gatilhos e acompanhamento</h3><div class="dialog-plan"><strong>Consolidação quadrimestral:${row.quarterScore===null?'ainda não fechada':fmt(row.quarterScore,2)+' pontos'}</strong>Campos nulos:${fmt(row.nullFieldsPct)}%; BOs acima de 72h:${fmt(row.late72Pct)}% em 30 dias; rejeição:${fmt(row.rejectionPct)}%.<br>${audit?`<strong>${audit.id} · ${audit.status}</strong>${audit.finished}/${audit.total} itens examinados; ${audit.phase}.<br>`:'<strong>Monitoramento</strong>Sem inspeção selecionada no plano demonstrativo.<br>'}${p?`<strong>PAI simulado · ${p.progress}% das ações</strong>${p.signals.map(esc).join('; ')}. Responsáveis:UF e DGI. Revisão:${p.due}.`:'Sem PAI aberto pelos gatilhos apurados neste cenário.'}<br>A janela de dois quadrimestres não é aferida por falta de segundo período. Critérios divergentes dos documentos estão explicados na metodologia.</div><div class="dialog-meta"><span>Participação:${row.attendance}%</span><span>Compromissos:${row.completedCommitments}/${row.commitments}</span><span>Práticas:${row.practices}</span></div></div>`;$('#uf-dialog').showModal();}
function csv(){if(ui.view==='analitico'){analyticsController.onExport();return;}let header,values,name;const r=ui.view==='ranking'?rankingRows():filtered();if(ui.view==='checklist'){header=['ITEM','FASE','TITULO','ACAO','CRITERIO','RESULTADO','EVIDENCIA_OBSERVACOES'];const current=answers();values=checklistContent.itens.filter(i=>!checklistUI.phase||String(i.fase)===checklistUI.phase).map(i=>[i.id,i.fase,i.titulo,i.acao,i.criterio,current[i.id]?.result||'Não aferido',current[i.id]?.note||'']);name='checklist';}else if(ui.view==='auditorias'){header=['VERIFICACAO','UF','TIPO','ETAPA','RESPONSAVEL','REVISOR','MARCO_PROPOSTO','ITENS_CONFERIDOS','ITENS_CHECKLIST','ACHADOS','PRIORIDADE_ALTA'];values=filteredAudits().map(a=>[a.id,a.uf,a.type,a.status,a.owner,a.reviewer,`D+${a.deadline}`,a.finished,a.total,a.findings,a.critical]);name='verificacoes';}else{header=['POSICAO_NACIONAL','UF','NOME','REGIAO','IQD_BASE_SEM_BONUS','CT_PERCENTUAL','CC_PERCENTUAL','TM_24H_PERCENTUAL','CN_PERCENTUAL','CE_PERCENTUAL_COMPLEMENTAR','FAIXA_BASE','EVOLUCAO_PP_DESDE_D30','PAI_SIMULADO','DELEGACIAS_ENVIO_DIARIO','TOTAL_DELEGACIAS','BO_LOCAL','BO_RECEBIDO','BO_RECEBIDO_ATE_24H','BO_ACIMA_72H','NULOS_PERCENTUAL','REJEICAO_PERCENTUAL','IQD_QUADRIMESTRAL','MODALIDADE_FICTICIA','LATENCIA_MEDIANA_HORAS_SIMULADA','BONUS_PPE_API','FATOR_FNSP_PROPOSTO','COMPROMISSOS_CONCLUIDOS','COMPROMISSOS_PREVISTOS'];values=r.map(a=>[a.rank,a.uf,a.name,a.region,a.score,a.ct,a.cc,a.tm,a.cn,a.ce,band(a.score),a.delta,needsPlan(a)?'SIM':'NAO',a.dailyUnits,a.totalUnits,a.localBO,a.receivedBO,a.timelyBO,a.late72BO,a.nullFieldsPct,a.rejectionPct,a.quarterScore??'NAO_FECHADO',a.modality.name,a.latencyHours,'A_PACTUAR_NAO_APLICADO',fiscalProposal(a.score).factor??'SEM_FATOR',a.completedCommitments,a.commitments]);name='ranking';}const quote=v=>`"${String(v).replaceAll('"','""')}"`;const lines=[['DADOS FICTICIOS - PROTOTIPO ACADEMICO SUSPERITOS'],[methodologyVersion],[`Ciclo${ui.cycle+1} - ${cycles[ui.cycle]} - implantacao hipotetica`],[`Recorte:${ui.region||'Brasil'} / ${ui.uf||'Todas as UFs'}; fatores financeiros sao proposta sem efeito automatico`],header,...values];const safe=v=>typeof v==='string'&&/^[=+@\-]/.test(v)?"'"+v:v;const blob=new Blob(['\ufeff'+lines.map(l=>l.map(v=>quote(safe(v))).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`SUSPeritos_DADOS_FICTICIOS_${name}_ciclo_${ui.cycle+1}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast(`CSV com${values.length} registros de demonstração exportado.`);}

$('#sidebar-note-icon').innerHTML=ico('layers',26);$('#menu-toggle').innerHTML=ico('menu',22);$('#contrast').innerHTML=ico('contrast',18);
$('#cycle').addEventListener('change',e=>{ui.cycle=Number(e.target.value);render();});
$('#region').addEventListener('change',e=>{ui.region=e.target.value;ui.uf='';updateStateOptions();render();});
$('#state').addEventListener('change',e=>{ui.uf=e.target.value;render();});
$('#reset').addEventListener('click',()=>{analyticsController.reset();ui.region='';ui.uf='';ui.search='';ui.band='';ui.auditStatus='';ui.rankingMode='score';$('#region').value='';updateStateOptions();render();toast('Filtros limpos. O ciclo selecionado foi mantido.');});
$('#export').addEventListener('click',csv);
$('#contrast').addEventListener('click',e=>{const on=document.body.classList.toggle('high-contrast');$('#contrast').setAttribute('aria-pressed',on);$('#contrast').setAttribute('aria-label',on?'Desativar alto contraste':'Ativar alto contraste');});
$('#menu-toggle').addEventListener('click',()=>{const on=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',on);});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-view'))go(b.dataset.view);
 if(b.hasAttribute('data-uf'))showUF(b.dataset.uf);
 if(b.hasAttribute('data-close-dialog'))$('#uf-dialog').close();
 if(b.hasAttribute('data-order')){ui.rankingMode=b.dataset.order;render();}
 if(b.hasAttribute('data-band')){ui.band=b.dataset.band;go('ranking');}
 if(b.hasAttribute('data-audit-status')){ui.auditStatus=b.dataset.auditStatus;render();}
 if(b.hasAttribute('data-audit')){const row=document.getElementById(b.dataset.audit);row.hidden=!row.hidden;b.setAttribute('aria-expanded',!row.hidden);}
});
document.addEventListener('click',e=>{const point=e.target.closest('[data-trend]');if(point)toast(point.dataset.trend);});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.hasAttribute('data-trend')){e.preventDefault();toast(e.target.dataset.trend);}});
document.addEventListener('input',e=>{if(e.target.id==='ranking-search'){ui.search=e.target.value;$('#ranking-table').innerHTML=rankingTable(rankingRows(),true);$('#ranking-count').textContent=`${rankingRows().length} UFs exibidas · ¹ Evolução em pontos do IQD desde D+30.`;}});
document.addEventListener('change',e=>{if(e.target.id==='band-filter'){ui.band=e.target.value;render();}if(e.target.id==='ranking-order'){ui.rankingMode=e.target.value;render();}});
$('#uf-dialog').addEventListener('click',e=>{if(e.target===$('#uf-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
const initial=location.hash.slice(1);if(headings[initial])ui.view=initial;updateStateOptions();render();

document.addEventListener('change',e=>{
 if(e.target.id==='checklist-phase'){checklistUI.phase=e.target.value;render();}
 if(e.target.hasAttribute('data-check-result')){const id=e.target.dataset.checkResult;answers()[id]={...(answers()[id]||{}),result:e.target.value};render();}
});
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-check-note')){const id=e.target.dataset.checkNote;answers()[id]={...(answers()[id]||{}),note:e.target.value};}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.hasAttribute('data-clear-checklist')){delete checklistUI.answers[answerKey()];render();toast('Preenchimento demonstrativo deste recorte limpo.');}});
